from typing import List

Poly = List[int]  # coefficients, lowest degree first


def mulmod_f(a: Poly, b: Poly, p: int) -> Poly:
    """Product of two residues modulo f = x^3 - 4x + 1 over F_p (reduce with x^3 = 4x - 1)."""
    prod = [0] * 5
    for i, ai in enumerate(a):
        for j, bj in enumerate(b):
            prod[i + j] = (prod[i + j] + ai * bj) % p
    for k in (4, 3):
        c, prod[k] = prod[k], 0
        prod[k - 2] = (prod[k - 2] + 4 * c) % p
        prod[k - 3] = (prod[k - 3] - c) % p
    return prod[:3]


def trim(a: Poly) -> Poly:
    a = a[:]
    while a and a[-1] == 0:
        a.pop()
    return a


def polymod(a: Poly, b: Poly, p: int) -> Poly:
    a, b = trim(a), trim(b)
    inv = pow(b[-1], p - 2, p)
    while len(a) >= len(b):
        c, shift = a[-1] * inv % p, len(a) - len(b)
        for i, bi in enumerate(b):
            a[shift + i] = (a[shift + i] - c * bi) % p
        a = trim(a)
    return a


def root_count(p: int) -> int:
    """Number of roots of x^3 - 4x + 1 modulo an odd prime p != 229, as deg gcd(x^p - x, f)."""
    result, base, e = [1, 0, 0], [0, 1, 0], p
    while e:
        if e & 1:
            result = mulmod_f(result, base, p)
        base = mulmod_f(base, base, p)
        e >>= 1
    result[1] = (result[1] - 1) % p          # x^p - x mod f
    if not trim(result):
        return 3
    a, b = [1, (-4) % p, 0, 1], trim(result)
    while b:
        a, b = b, polymod(a, b, p)
    return len(a) - 1


if __name__ == "__main__":
    print({p: root_count(p) for p in (3, 5, 7, 11, 13, 461, 1009)})

import math
from collections import Counter
from itertools import permutations
from typing import Callable, Hashable, Tuple

Perm = Tuple[int, ...]


def cycle_type(s: Perm) -> Tuple[int, ...]:
    seen, lens = set(), []
    for i in range(len(s)):
        if i not in seen:
            j, n = i, 0
            while j not in seen:
                seen.add(j); j = s[j]; n += 1
            lens.append(n)
    return tuple(sorted(lens, reverse=True))


def sign(s: Perm) -> int:
    return (-1) ** sum(l - 1 for l in cycle_type(s))


def legendre(a: int, ell: int) -> int:
    return 1 if pow(a, (ell - 1) // 2, ell) == 1 else -1


def entropy(counts) -> float:
    c = [x for x in counts if x]
    n = sum(c)
    return math.log2(n) - sum(x * math.log2(x) for x in c) / n


def fibre_product_channel(n: int, ell: int, readout: Callable[[Perm], Hashable]) -> float:
    """Exact I(readout(sigma); r) on {(sigma, r) in S_n x (Z/ell)^* : sign sigma = (r/ell)}."""
    pairs = [(readout(s), r) for s in permutations(range(n)) for r in range(1, ell)
             if sign(s) == legendre(r, ell)]
    hx = entropy(Counter(x for x, _ in pairs).values())
    hy = entropy(Counter(y for _, y in pairs).values())
    return hx + hy - entropy(Counter(pairs).values())


if __name__ == "__main__":
    for n in (2, 3, 4, 5):
        print(n, fibre_product_channel(n, 7, cycle_type))              # always 1.0
    print(fibre_product_channel(3, 229, lambda s: sum(i == j for i, j in enumerate(s))))  # 1.0
    print(fibre_product_channel(4, 7, lambda s: sum(i == j for i, j in enumerate(s))))    # < 1

