def predicted_one_root(p: int, D: int = 229) -> bool:
    """Splitting-Type Law: for primes p not in {2, 229}, x^3 - 4x + 1 has exactly one root mod p
    iff p is a quadratic non-residue mod 229, i.e. p^((229-1)/2) = p^114 == -1 (mod 229)."""
    return pow(p % D, (D - 1) // 2, D) == D - 1


def brute_force_one_root(p: int) -> bool:
    return sum(1 for x in range(p) if (x ** 3 - 4 * x + 1) % p == 0) == 1


if __name__ == "__main__":
    primes = [q for q in range(3, 5000) if all(q % d for d in range(2, int(q ** 0.5) + 1))]
    assert all(predicted_one_root(q) == brute_force_one_root(q) for q in primes if q != 229)
    print("law confirmed for", len(primes) - 1, "primes below 5000")

