"""Splitting types of x^3 - 4x + 1 against the residue class of p modulo 229."""
from typing import List, Tuple
import matplotlib.pyplot as plt

D = 229


def primes_up_to(n: int) -> List[int]:
    s = bytearray([1]) * (n + 1); s[0:2] = b"\x00\x00"
    for i in range(2, int(n ** 0.5) + 1):
        if s[i]:
            s[i * i::i] = bytearray(len(s[i * i::i]))
    return [i for i in range(n + 1) if s[i]]


def root_count(p: int) -> int:
    return sum(1 for x in range(p) if (x * x * x - 4 * x + 1) % p == 0)


def legendre(a: int, p: int) -> int:
    return 1 if pow(a % p, (p - 1) // 2, p) == 1 else -1


def main() -> None:
    data: List[Tuple[int, int, int]] = []
    for p in primes_up_to(30000):
        if p in (2, D):
            continue
        data.append((p, p % D, root_count(p)))
    colors = {0: "#4c72b0", 1: "#dd5555", 3: "#2ca02c"}
    fig, (ax, bx) = plt.subplots(1, 2, figsize=(13, 5), gridspec_kw={"width_ratios": [3, 1]})
    for t in (0, 1, 3):
        xs = [c for _, c, k in data if k == t]
        ys = [p for p, _, k in data if k == t]
        ax.scatter(xs, ys, s=4, c=colors[t], label=f"{t} roots")
    for c in range(1, D):
        if legendre(c, D) == -1:
            ax.axvspan(c - 0.5, c + 0.5, color="#dd5555", alpha=0.06, lw=0)
    ax.set_xlabel("residue class p mod 229  (shaded = quadratic non-residue)")
    ax.set_ylabel("prime p")
    ax.set_title("Exactly one root  <=>  p is a non-residue mod 229")
    ax.legend(markerscale=4, loc="upper right")
    labels = ["residue class", "non-residue class"]
    for i, side in enumerate((1, -1)):
        tot = [sum(1 for p, _, k in data if k == t and legendre(p, D) == side) for t in (3, 1, 0)]
        bottom = 0
        for t, h in zip((3, 1, 0), tot):
            bx.bar(i, h, bottom=bottom, color=colors[t])
            bottom += h
    bx.set_xticks([0, 1]); bx.set_xticklabels(labels)
    bx.set_title("Types on each half (never 2 roots)")
    plt.tight_layout(); plt.savefig("splitting_types_229.png", dpi=150); plt.show()


if __name__ == "__main__":
    main()

"""Plug-in mutual information over the first N primes converging to the exact value of 1 bit."""
import math
from collections import Counter
from typing import Iterable, List, Tuple
import matplotlib.pyplot as plt

D = 229


def primes_up_to(n: int) -> List[int]:
    s = bytearray([1]) * (n + 1); s[0:2] = b"\x00\x00"
    for i in range(2, int(n ** 0.5) + 1):
        if s[i]:
            s[i * i::i] = bytearray(len(s[i * i::i]))
    return [i for i in range(n + 1) if s[i]]


# --- fast root counting: deg gcd(x^p - x, f) over F_p ------------------------

Poly = List[int]  # coefficients, lowest degree first


def _mulmod_f(a: Poly, b: Poly, p: int) -> Poly:
    """Multiply two polynomials of degree < 3 modulo f = x^3 - 4x + 1 over F_p."""
    prod = [0] * 5
    for i, ai in enumerate(a):
        if ai:
            for j, bj in enumerate(b):
                prod[i + j] = (prod[i + j] + ai * bj) % p
    # reduce with x^3 = 4x - 1
    for k in (4, 3):
        c = prod[k]
        if c:
            prod[k] = 0
            prod[k - 2] = (prod[k - 2] + 4 * c) % p
            prod[k - 3] = (prod[k - 3] - c) % p
    return prod[:3]


def _xpow_mod_f(e: int, p: int) -> Poly:
    result: Poly = [1, 0, 0]
    base: Poly = [0, 1, 0]
    while e:
        if e & 1:
            result = _mulmod_f(result, base, p)
        base = _mulmod_f(base, base, p)
        e >>= 1
    return result


def _trim(a: Poly) -> Poly:
    a = a[:]
    while a and a[-1] == 0:
        a.pop()
    return a


def _polymod(a: Poly, b: Poly, p: int) -> Poly:
    a = _trim(a)
    b = _trim(b)
    inv = pow(b[-1], p - 2, p)
    while len(a) >= len(b):
        c = a[-1] * inv % p
        shift = len(a) - len(b)
        for i, bi in enumerate(b):
            a[shift + i] = (a[shift + i] - c * bi) % p
        a = _trim(a)
    return a


def _gcd_deg(a: Poly, b: Poly, p: int) -> int:
    a, b = _trim(a), _trim(b)
    while b:
        a, b = b, _polymod(a, b, p)
    return len(a) - 1


def root_count(p: int) -> int:
    """Number of distinct roots of f mod p, for p not dividing 2*229."""
    if p < 50:
        return sum(1 for x in range(p) if (x * x * x - 4 * x + 1) % p == 0)
    g = _xpow_mod_f(p, p)
    g[1] = (g[1] - 1) % p          # x^p - x  mod f
    f: Poly = [1, (-4) % p, 0, 1]
    if not _trim(g):
        return 3                     # f divides x^p - x: splits completely
    return _gcd_deg(f, g, p)




def entropy(counts: Iterable[int]) -> float:
    c = [x for x in counts if x]
    n = sum(c)
    return math.log2(n) - sum(x * math.log2(x) for x in c) / n


def mi(pairs: List[Tuple[int, int]]) -> float:
    return (entropy(Counter(a for a, _ in pairs).values()) + entropy(Counter(b for _, b in pairs).values())
            - entropy(Counter(pairs).values()))


def main() -> None:
    data = [(p % D, root_count(p)) for p in primes_up_to(200000) if p not in (2, D)]
    Ns = list(range(300, len(data) + 1, 150))
    vals = [mi(data[:N]) for N in Ns]
    fig, (ax, bx) = plt.subplots(1, 2, figsize=(12, 4.5))
    ax.plot(Ns, vals, color="#5a2d82", label="plug-in estimate")
    ax.axhline(1.0, ls="--", color="k", label="exact law: 1 bit")
    ax.axhline(1.0078, ls=":", color="#dd5555", label="reported 1.0078")
    ax.set_xlabel("number of primes N"); ax.set_ylabel("bits"); ax.legend(); ax.set_title("Estimate -> 1 bit")
    bx.loglog(Ns, [v - 1 for v in vals], color="#5a2d82", label="excess over 1 bit")
    bx.loglog(Ns, [Ns[0] * (vals[0] - 1) / N for N in Ns], ls="--", color="gray", label="slope -1 reference")
    bx.set_xlabel("N"); bx.legend(); bx.set_title("Excess decays like 1/N (bias, not signal)")
    plt.tight_layout(); plt.savefig("mi_convergence_229.png", dpi=150); plt.show()


if __name__ == "__main__":
    main()
